RSpec.describe "Timekeeping write delay hook spec distinct cases" do
  # "delete write_delay_hook_2_spec.rb" and "Keep every distinct case once."
  # The deleted file checked the delay after every refused request, so the kept file must too.
  it "checks a zero write delay after each refused delay request in the single write delay hook spec" do
    spec_dir = Rails.root.join("timekeeping/spec/requests/internal/v1")
    expect(File.exist?(spec_dir.join("write_delay_hook_2_spec.rb"))).to be(false)

    source = File.read(spec_dir.join("write_delay_hook_spec.rb"))
    per_request_check = %r{\.each do \|\w+\|.*?/internal/v1/test-hooks/writes/delay.*?write_delay_seconds\.to_f\)\.to eq\(0\.0\).*?\bend\b}m

    expect(source).to match(per_request_check)
    expect(source).to include('"Bearer #{service_token}x"')
  end
end
